-- Schema v6, derived from committed entity declarations at 6451107.
CREATE TABLE `daily_steps` (`epochDay` INTEGER NOT NULL, `steps` INTEGER NOT NULL, `goal` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, PRIMARY KEY(`epochDay`));
CREATE TABLE `walk_sessions` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `startedAt` INTEGER NOT NULL, `endedAt` INTEGER NOT NULL, `steps` INTEGER NOT NULL, `durationSec` INTEGER NOT NULL, `distanceMeters` REAL NOT NULL, `calories` REAL NOT NULL, `pointsEarned` REAL NOT NULL);
CREATE TABLE `rewards` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `timestamp` INTEGER NOT NULL, `type` TEXT NOT NULL, `amount` REAL NOT NULL, `description` TEXT NOT NULL);
CREATE TABLE `sneakers` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `factionId` TEXT NOT NULL, `rarity` TEXT NOT NULL, `variant` INTEGER NOT NULL, `level` INTEGER NOT NULL, `mintNumber` INTEGER NOT NULL, `luck` REAL NOT NULL, `comfort` REAL NOT NULL, `durability` INTEGER NOT NULL, `equipped` INTEGER NOT NULL, `acquiredAt` INTEGER NOT NULL);
CREATE TABLE `boosts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `type` TEXT NOT NULL, `activatedAt` INTEGER NOT NULL, `expiresAt` INTEGER NOT NULL);
CREATE TABLE `claimed_events` (`eventId` TEXT NOT NULL, `claimedAt` INTEGER NOT NULL, `amount` REAL NOT NULL, PRIMARY KEY(`eventId`));
CREATE TABLE `crew_memberships` (`crewId` TEXT NOT NULL, `joinedAt` INTEGER NOT NULL, PRIMARY KEY(`crewId`));
CREATE TABLE `crews` (`id` TEXT NOT NULL, `name` TEXT NOT NULL, `monogram` TEXT NOT NULL, `tagline` TEXT NOT NULL, `area` TEXT NOT NULL, `kmAway` REAL NOT NULL, `memberCount` INTEGER NOT NULL, `roster` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `owned` INTEGER NOT NULL, PRIMARY KEY(`id`));
CREATE TABLE `posts` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `category` TEXT NOT NULL, `crewId` TEXT NOT NULL, `author` TEXT NOT NULL, `title` TEXT NOT NULL, `body` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `likes` INTEGER NOT NULL, `liked` INTEGER NOT NULL, `commentCount` INTEGER NOT NULL, `mine` INTEGER NOT NULL, `place` TEXT NOT NULL, `distanceKm` REAL NOT NULL, `meetAt` INTEGER NOT NULL, `capacity` INTEGER NOT NULL, `joinedCount` INTEGER NOT NULL, `joined` INTEGER NOT NULL);
CREATE TABLE `courses` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `area` TEXT NOT NULL, `distanceKm` REAL NOT NULL, `elevationM` INTEGER NOT NULL, `track` TEXT NOT NULL, `author` TEXT NOT NULL, `mine` INTEGER NOT NULL, `shared` INTEGER NOT NULL, `likes` INTEGER NOT NULL, `liked` INTEGER NOT NULL, `runCount` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL);
CREATE TABLE `comments` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `postId` INTEGER NOT NULL, `parentId` INTEGER NOT NULL, `author` TEXT NOT NULL, `body` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `mine` INTEGER NOT NULL);
CREATE TABLE `notifications` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `timestamp` INTEGER NOT NULL, `type` TEXT NOT NULL, `argText` TEXT NOT NULL, `argAmount` REAL NOT NULL, `argExtra` TEXT NOT NULL, `read` INTEGER NOT NULL, `actioned` INTEGER NOT NULL);
